// TapeLike is implemented by *Tape, by the classes deriving from Tape and by Go types embedding
// one of them: they all pass where C++ expects a datamunge::Tape.
type TapeLike interface {
	AsTape() *Tape
}

// Tape wraps the C++ class datamunge::Tape.
//
// SWIG-friendly facade for datamunge::autodiff::Tape -- a reverse-mode
// ("backpropagation") computation tape. Create leaf Vars against a Tape, build an
// expression out of named Var operations, then call backward() on the output Var
// to get the derivative of that output with respect to every node on the tape
// (index a leaf's own index() into the result to read its gradient).
//
// [Tape.Close] releases the C++ object; otherwise the garbage collector does.
type Tape struct {
	ref *rosetta.Handle
}

func makeTape(h *rosetta.Handle) Tape {
	return Tape{ref: h}
}

func (t *Tape) nativeRef() *rosetta.Handle {
	if t == nil {
		return nil
	}
	return t.ref
}

// AsTape returns the object as a [Tape] (itself), or nil for a nil receiver.
func (t *Tape) AsTape() *Tape {
	return t
}

// Close releases the C++ object now (it is idempotent); later calls fail with a [BindingError].
func (t *Tape) Close() { rosetta.Close(t.nativeRef()) }

// IsClosed reports whether the C++ object is released.
func (t *Tape) IsClosed() bool { return t.nativeRef().Closed() }

// String names the object's class (fmt.Stringer).
func (t *Tape) String() string { return rosetta.Describe(t.nativeRef()) }

// NewTape calls the C++ constructor datamunge::Tape.
//
// An empty tape; create leaf Vars against it with Var(tape, value).
func NewTape() (*Tape, error) {
	return rosetta.Construct[*Tape](2927, nil)
}

// Size calls the C++ method datamunge::Tape::size.
//
// Number of recorded nodes (leaves plus operation results).
func (t *Tape) Size() (int, error) {
	return rosetta.Result[int](rosetta.Call(2924, t))
}

// ValueAt calls the C++ method datamunge::Tape::value_at.
//
// The value recorded at node `index`.
//
// Parameters:
//
//   - index: Node index, as returned by Var::index().
//
// It returns the node's value.
//
// The error is an [*Error] of kind:
//
//   - [OutOfRange] (C++ std::out_of_range): When `index` >= size().
func (t *Tape) ValueAt(index int) (float64, error) {
	return rosetta.Result[float64](rosetta.Call(2925, t, index))
}

// Backward calls the C++ method datamunge::Tape::backward.
//
// Reverse sweep from `output`: d(output)/d(node) for every node on the tape.
//
// The tape is unchanged, so backward() may be called again for other outputs.
//
// # Example
//
//	dm::Tape tape;
//	const dm::Var a(tape, 2.0), b(tape, 3.0);
//	const auto grad = tape.backward(a.multiply(b));
//	std::print("{} {}\n", grad[a.index()], grad[b.index()]);  // 3 2
//
// Parameters:
//
//   - output: A Var recorded on this tape (usually the final expression).
//
// It returns one adjoint per node, indexed by Var::index() (0-based; add 1 in R and Lua).
//
// The error is an [*Error] of kind:
//
//   - [OutOfRange] (C++ std::out_of_range): When `output` is not a node of this tape.
func (t *Tape) Backward(output *Var) ([]float64, error) {
	return rosetta.Result[[]float64](rosetta.Call(2926, t, output))
}

// CadSolidLike is implemented by *CadSolid, by the classes deriving from CadSolid and by Go types
// embedding one of them: they all pass where C++ expects a datamunge::cad::Solid.
type CadSolidLike interface {
	AsCadSolid() *CadSolid
}

// CadSolid wraps the C++ class datamunge::cad::Solid.
//
// An owned B-rep solid with value-returning modelling and export operations.
// Geometry uses doubles in caller-selected consistent units. Copies own topology;
// immutable surfaces may be shared. Operations return new solids, preserving inputs.
// Unsupported kernel operations throw std::runtime_error with the kernel diagnostic.
// Concurrent const access is safe; do not mutate a shared object concurrently.
//
// # Example
//
//	auto block = dm::cad::Solid::box(4, 3, 2);
//	auto hole = dm::cad::Solid::cylinder(.4, 4).translated(2, 1.5, -1);
//	auto part = block.subtracted(hole);
//	part.save("part.step");
//
// [CadSolid.Close] releases the C++ object; otherwise the garbage collector does.
//
// See also Model, FeatureTree and load_scene().
type CadSolid struct {
	ref *rosetta.Handle
}

func makeCadSolid(h *rosetta.Handle) CadSolid {
	return CadSolid{ref: h}
}

func (c *CadSolid) nativeRef() *rosetta.Handle {
	if c == nil {
		return nil
	}
	return c.ref
}

// AsCadSolid returns the object as a [CadSolid] (itself), or nil for a nil receiver.
func (c *CadSolid) AsCadSolid() *CadSolid {
	return c
}

// Close releases the C++ object now (it is idempotent); later calls fail with a [BindingError].
func (c *CadSolid) Close() { rosetta.Close(c.nativeRef()) }

// IsClosed reports whether the C++ object is released.
func (c *CadSolid) IsClosed() bool { return c.nativeRef().Closed() }

// String names the object's class (fmt.Stringer).
func (c *CadSolid) String() string { return rosetta.Describe(c.nativeRef()) }

