// NnTensorLike is implemented by *NnTensor, by the classes deriving from NnTensor and by Go types
// embedding one of them: they all pass where C++ expects a datamunge::nn::NnTensor.
type NnTensorLike interface {
	AsNnTensor() *NnTensor
}

// NnTensor wraps the C++ class datamunge::nn::NnTensor.
//
// [NnTensor.Close] releases the C++ object; otherwise the garbage collector does.
type NnTensor struct {
	ref *rosetta.Handle
}

func makeNnTensor(h *rosetta.Handle) NnTensor {
	return NnTensor{ref: h}
}

func (n *NnTensor) nativeRef() *rosetta.Handle {
	if n == nil {
		return nil
	}
	return n.ref
}

// AsNnTensor returns the object as a [NnTensor] (itself), or nil for a nil receiver.
func (n *NnTensor) AsNnTensor() *NnTensor {
	return n
}

// Close releases the C++ object now (it is idempotent); later calls fail with a [BindingError].
func (n *NnTensor) Close() { rosetta.Close(n.nativeRef()) }

// IsClosed reports whether the C++ object is released.
func (n *NnTensor) IsClosed() bool { return n.nativeRef().Closed() }

// String returns the C++ to_string() text (fmt.Stringer).
func (n *NnTensor) String() string {
	return rosetta.Stringify(n.ToString())
}

