func SimplifyPolyline(points []*Point2D, epsilon float64) ([]*Point2D, error) {
	return rosetta.Result[[]*Point2D](rosetta.Call(162, points, epsilon))
}

// Circumcenter calls C++ datamunge::geometry::detail::circumcenter.
func Circumcenter(a *Point2D, b *Point2D, c *Point2D) (*Point2D, error) {
	return rosetta.Result[*Point2D](rosetta.Call(163, a, b, c))
}

// VoronoiDiagram2 calls C++ datamunge::geometry::voronoi_diagram.
//
// The Voronoi diagram of `points`, computed as the dual of their Delaunay
