//
// See also [HypothesisTestResult].
func TTestTwoSampleWithEqualVariance(x []float64, y []float64, equalVariance bool) (*HypothesisTestResult, error) {
	return rosetta.Result[*HypothesisTestResult](rosetta.Call(202, x, y, equalVariance))
}

