//   - [InvalidArgument] (C++ std::invalid_argument): On empty/mismatched inputs, invalid lambdas,
//     or an axis with no more functions than `order`.
//   - [NativeError] (C++ std::runtime_error): If the penalized normal equations are singular.
//
// See also fit_tensor_bspline() and fit_pspline().
func FitTensorPsplineWithOptions(bases []*BSplineBasis, points [][]float64, values []float64, lambdas []float64, order int, options *SplineSolveOptions) (*TensorBSpline, error) {
	return rosetta.Result[*TensorBSpline](rosetta.Call(219, bases, points, values, lambdas, order, options))
}

